        "source_id": "new-10",
        "side": "new",
        "speaker": "user",
        "text": "I'm really looking forward to finding a position that supports both my career goals and my personal health. It's been a challenging journey, but I'm hopeful about the future.",
        "recorded_at": "Feb 05, 2026, 17:37:37",
